import { createMapNode, TileGrid } from '../map/TileGrid.js';
import { MapNavigator } from '../map/MapNavigator.js';
import { PartyTracker } from '../party/PartyTracker.js';
import { partySight } from '../party/Sight.js';
import { pruneEntries } from '../map/EntryMemory.js';
import { toTileGrid } from '../storage/SaveManager.js';
import { campaignFields } from '../storage/CampaignFields.js';
import { loadPersistedCampaign } from '../storage/PersistedCampaign.js';
import { loadTruncation } from '../storage/ShortenedLoad.js';
import { createClock } from '../time/GameClock.js';
import { buildExampleWorld } from './ExampleWorld.js';
import { buildExampleContent } from './ExampleContent.js';

/** @typedef {import('../map/TilePalette.js').TilePalette} TilePalette */
/** @typedef {import('../storage/ShortenedLoad.js').Truncation} Truncation */

/**
 * Everything that makes up one campaign's state at runtime. SaveManager's
 * CampaignState is the serialized form of this state.
 * @typedef {{
 *   grid: TileGrid,
 *   party: import('../types/map.js').PartyPosition,
 *   entryTiles: import('../map/EntryMemory.js').EntryMemory,
 *   characters: import('../types/entities.js').Character[],
 *   creatures: import('../types/creature.js').Creature[],
 *   travelog: import('../types/log.js').LogEntry[],
 *   quests: import('../types/quest.js').Quest[],
 *   clock: import('../types/time.js').GameClock,
 *   handouts: import('../types/handout.js').Handout[],
 *   bestiary: import('../types/creature.js').CreatureTemplate[],
 *   splitParty: boolean,
 *   combat: import('../types/combat.js').CombatState | null,
 * }} Campaign
 */

/**
 * Whether the live campaign holds nothing the GM could lose: one world node
 * with no tiles, and no characters. The onboarding overlay shows only for
 * such a campaign, and "Load example" skips its replace warning for it.
 * @param {{ nodeCount(): number }} grid
 * @param {{ tiles: readonly unknown[] }} currentNode
 * @param {readonly unknown[]} characters
 * @returns {boolean}
 */
export function isBlankCampaign(grid, currentNode, characters) {
  return grid.nodeCount() === 1 && currentNode.tiles.length === 0 && characters.length === 0;
}

/**
 * A blank campaign has one empty world node, no characters in the party, and
 * no enemies. The first run of the app and the "New" button produce this
 * campaign. Demo content appears only when the GM asks for it.
 * @returns {Campaign}
 */
export function buildBlankCampaign() {
  const grid = new TileGrid();
  grid.addNode(createMapNode('world', 'World', null, 8, 6));
  return {
    grid,
    party: { nodeId: 'world', tileId: '0,0' },
    ...campaignFields({}),
    clock: createClock(),
  };
}

/**
 * The example campaign loads on demand through the "Load example" button. Its
 * world is a generated 48x48 continent of nine regions, each with its own
 * towns, keeps, dungeons, and caves, populated end to end as a playable story.
 *
 * Goblin raids out of the Northmarch march under the seal of King Ostrand,
 * the risen wight in the Barrow of the Old King. The quest chain runs from
 * crossroads rumors through the raiders' camp (Chieftain Snagtooth), the
 * wyvern Skalvyr guarding the hermit who holds the barrow's warding key, an
 * optional bargain with the mire hag, and down into the barrow to put
 * Ostrand back in his tomb.
 *
 * Field enemies appear in each biome. Briarwick has NPCs. Handouts, a
 * bestiary, and the party complete the demo. The maps come from
 * ExampleWorld.js, from a fixed seed, so every load builds the same campaign.
 * The populace comes from ExampleContent.js. The fog around the start tile
 * is cleared here, because the boot path places the party on a loaded save
 * without a reveal.
 * @param {TilePalette} palette
 * @returns {Campaign}
 */
export function buildExampleCampaign(palette) {
  const world = buildExampleWorld(palette);
  const campaign = { grid: world.grid, ...buildExampleContent(world) };
  new PartyTracker(campaign.grid, campaign.party, {
    sight: partySight(
      () => campaign.clock,
      () => campaign.characters,
    ),
  });
  return campaign;
}

/**
 * The app boots with the saved campaign if a save exists. If no save exists,
 * the app boots with a blank campaign. The demo world loads only through the
 * "Load example" button, never by default. An empty character roster is
 * valid authored state, so the app never adds a default character.
 *
 * The save is read through the history log, which keeps the parsed state
 * as the base for the first delta of the session. The grid then holds those
 * same node objects, so that first diff runs by identity. A caller that has
 * already read the save passes it in.
 * @param {import('../types/storage.js').CampaignState | null} [saved]
 * @returns {Campaign}
 */
export function loadInitialCampaign(saved = loadPersistedCampaign()) {
  if (!saved) return buildBlankCampaign();
  // A campaign with no map has nowhere to put the party or the map view.
  if (saved.nodes.length === 0) throw new Error('The saved campaign has no map nodes.');
  // SaveManager's deserialize sets a default for every missing top-level field
  // and runs withDefaults for each entity. saved is a complete CampaignState
  // here. Only party and clock still need a runtime default, because
  // deserialize fills them with null.
  const grid = toTileGrid(saved);
  return {
    grid,
    party: partyOnGrid(saved.party, grid),
    // An entry for a node that another tab deleted names nothing. Dropping
    // it here keeps it out of the next save.
    ...campaignFields(saved),
    entryTiles: pruneEntries(saved.entryTiles, (nodeId) => grid.getNode(nodeId) !== undefined),
    clock: saved.clock ?? createClock(),
  };
}

/**
 * A runtime campaign over a state whose objects are already live. The
 * cross-tab delta adoption builds such a state: it applies a saved delta to
 * this tab's own state, so every entity the delta did not touch is the live
 * object the views already hold. Unlike `loadInitialCampaign`, nothing here
 * re-parses or re-defaults. The entities came from live state on both sides
 * of the delta, so they already carry their defaults.
 * @param {import('../types/storage.js').CampaignState} state
 * @returns {Campaign}
 */
export function campaignFromLiveState(state) {
  const grid = new TileGrid();
  for (const node of state.nodes) grid.addNode(node);
  return {
    grid,
    party: partyOnGrid(state.party, grid),
    // The entry memory is not pruned here. A delta applied to live state is
    // already consistent, and a prune would walk the world on every adoption.
    ...campaignFields(state),
    clock: state.clock ?? createClock(),
  };
}

/**
 * The party position a loaded campaign boots with. A position that names a
 * node in the grid is kept. Any other position, including none, moves the
 * party to tile 0,0 of the first root node. The party tracker throws on a
 * node it cannot find, and an imported file can name any node it likes.
 * @param {import('../types/map.js').PartyPosition | null} party
 * @param {TileGrid} grid
 * @returns {import('../types/map.js').PartyPosition}
 */
export function partyOnGrid(party, grid) {
  if (party && grid.getNode(party.nodeId)) return party;
  const nodes = grid.allNodes();
  const root = nodes.find((node) => node.parentId === null) ?? nodes[0];
  if (!root) throw new Error('The campaign has no map nodes to put the party on.');
  return { nodeId: root.id, tileId: '0,0' };
}

/**
 * The boot entry point. It calls `loadInitialCampaign` and builds the map
 * navigator and the party tracker over the result. A save that the app
 * cannot read, or whose map these two objects refuse, produces a blank
 * campaign instead of an exception.
 *
 * Without this, one unreadable field causes a white screen. Import writes
 * what it reads before it reloads the app, so the unreadable campaign is
 * already the stored save, and the GM has no app left to press Undo
 * in. `failed` lets the caller report the error once the toasts mount. The
 * previous save is still in the undo history, and Undo restores it.
 * `truncated` is what the load left out when the save passes the decode
 * limits (`storage/ShortenedLoad.js`), or null.
 * @returns {{ campaign: Campaign, navigator: MapNavigator, partyTracker: PartyTracker, failed: boolean, truncated: Truncation | null }}
 */
export function loadInitialCampaignSafe() {
  try {
    const saved = loadPersistedCampaign();
    return {
      ...withTrackers(loadInitialCampaign(saved)),
      failed: false,
      truncated: loadTruncation(saved),
    };
  } catch (error) {
    console.error('Could not load the saved campaign; starting blank.', error);
    return { ...withTrackers(buildBlankCampaign()), failed: true, truncated: null };
  }
}

/**
 * A campaign with the navigator and party tracker that start on it. Both
 * throw on a node the grid does not hold. The tracker places the party
 * without a reveal, so fog that the GM hid near the party stays hidden after
 * a reload.
 * @param {Campaign} campaign
 */
function withTrackers(campaign) {
  const navigator = new MapNavigator(campaign.grid, campaign.party.nodeId);
  navigator.getCurrentNode();
  return {
    campaign,
    navigator,
    partyTracker: new PartyTracker(campaign.grid, campaign.party, {
      sight: partySight(
        () => campaign.clock,
        () => campaign.characters,
      ),
      reveal: false,
    }),
  };
}
