import { MapRenderer, imageSrcForRef } from './MapRenderer.js';
import { overlayList } from './TileGrid.js';
import { downloadBlob } from '../storage/fileIO.js';
import { MIN_LABELLED_TILE } from './CoordLabels.js';

/** @typedef {import('../types/map.js').MapNode} MapNode */

/**
 * Export a node's map as a PNG image. This draws the full extent to an
 * offscreen canvas at tile resolution and hands it to the browser as a
 * download. It is GM and Build mode only, enforced by the caller's UI
 * placement. The draw ignores fog of war, so a player-facing export leaks
 * the whole map.
 */

/**
 * Every image the node's tiles reference, both base tiles and overlays,
 * with duplicates removed. This is a pure function. The renderer preloads
 * images through it before drawing.
 * @param {MapNode} node
 * @returns {string[]}
 */
export function collectImageRefs(node) {
  const refs = new Set();
  for (const tile of node.tiles) {
    if (tile.imageRef) refs.add(tile.imageRef);
    for (const ref of overlayList(tile)) refs.add(ref);
  }
  return [...refs];
}

/**
 * A safe download filename from a node name. It keeps only word characters
 * and dashes, with a fallback for names that reduce to nothing. This is a
 * pure function.
 * @param {string} name
 * @returns {string}
 */
export function exportFilename(name) {
  const slug = name
    .replace(/[^\w-]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .toLowerCase();
  return `${slug || 'map'}.png`;
}

/**
 * The pixels per tile a handout export uses when the node fits. This is the
 * size of the source tile art, so a node under the limits below exports at
 * full resolution.
 */
export const EXPORT_TILE_SIZE = 64;

/**
 * The most pixels an export canvas may hold. Browsers cap the total area of
 * a canvas, and a canvas past the cap either throws or comes back blank. The
 * lowest cap in a browser this app runs in is Safari's 2^24 pixels, so that
 * is the budget here. Chrome and Firefox allow more, and a node that fits
 * this budget exports the same way in all of them.
 */
export const MAX_EXPORT_PIXELS = 16_777_216;

/**
 * The longest side an export canvas may have. A long thin node can fit the
 * area budget and still ask for a side no browser allocates. Safari stops at
 * 16,384 pixels, which is the lowest of the three.
 */
export const MAX_EXPORT_SIDE = 16_384;

/**
 * The smallest pixels per tile worth writing to a file. Below this the tile
 * art is a smear of color, so a node that needs less than this to fit the
 * budget is refused instead of exported unreadable.
 */
export const MIN_EXPORT_TILE_SIZE = 8;

/**
 * The margin, in pixels, that an export leaves on the top and left of the map
 * for the coordinate labels. The live view uses the same margin at a pixel
 * ratio of 1. Without it the labels draw on top of the first row and column
 * of tiles, and the corner rule of `visibleCoordLabels` drops column 1 and
 * row 1.
 */
export const EXPORT_LEAD = 64;

/**
 * The label margin an export at `tileSize` pixels per tile needs. Tiles too
 * small to label get no margin, because no labels draw. This is a pure
 * function.
 * @param {number} tileSize
 * @returns {number}
 */
export function exportLead(tileSize) {
  return tileSize >= MIN_LABELLED_TILE ? EXPORT_LEAD : 0;
}

/**
 * The canvas width and height of an export at `tileSize` pixels per tile,
 * label margin included. This is a pure function.
 * @param {MapNode} node
 * @param {number} tileSize
 * @returns {{ width: number, height: number, lead: number }}
 */
export function exportCanvasSize(node, tileSize) {
  const lead = exportLead(tileSize);
  return {
    width: Math.max(1, node.width * tileSize + lead),
    height: Math.max(1, node.height * tileSize + lead),
    lead,
  };
}

/**
 * The pixels per tile an export of this node can use, or 0 when even
 * `MIN_EXPORT_TILE_SIZE` asks for a canvas past the limits above. The answer
 * is never larger than `requested`: a node that fits keeps full resolution,
 * and a node too wide for the budget scales down instead of failing in the
 * browser. This is a pure function.
 * @param {MapNode} node
 * @param {number} [requested] pixels per tile the caller wants
 * @returns {number}
 */
export function exportTileSize(node, requested = EXPORT_TILE_SIZE) {
  const width = node.width;
  const height = node.height;
  if (!Number.isFinite(width) || !Number.isFinite(height)) return 0;
  const cells = Math.max(1, width) * Math.max(1, height);
  const byArea = Math.floor(Math.sqrt(MAX_EXPORT_PIXELS / cells));
  const bySide = Math.floor(MAX_EXPORT_SIDE / Math.max(1, width, height));
  const limit = Math.min(byArea, bySide);
  if (limit < MIN_EXPORT_TILE_SIZE) return 0;
  let size = Math.max(1, Math.min(requested, limit));
  // The label margin adds a few pixels to each side, so a size right at the
  // limit steps down until the canvas with its margin fits.
  while (size > 1) {
    const { width: w, height: h } = exportCanvasSize(node, size);
    if (w * h <= MAX_EXPORT_PIXELS && Math.max(w, h) <= MAX_EXPORT_SIDE) break;
    size -= 1;
  }
  return size >= Math.min(requested, MIN_EXPORT_TILE_SIZE) ? size : 0;
}

/**
 * The refs an export still must decode, given the images a live renderer
 * already holds. An entry that is present but not `complete` is still
 * loading, so the export loads its own copy instead of drawing a blank tile.
 * This is a pure function.
 * @param {string[]} refs
 * @param {Map<string, HTMLImageElement>} [cache]
 * @returns {string[]}
 */
export function refsToDecode(refs, cache) {
  if (!cache) return refs;
  return refs.filter((ref) => !cache.get(ref)?.complete);
}

/**
 * Draw a node's full extent to a fresh canvas at `tileSize` pixels per tile,
 * with fog of war ignored. The map starts `exportLead` pixels in from the
 * top and left, so every column and row label draws in that margin. Tile images are preloaded into the renderer's
 * cache first, so the single draw pass shows real art instead of
 * placeholders. An image that fails to load falls back to the renderer's
 * placeholder fill. Pass the live canvas's `imageCache` to reuse the art it
 * already decoded. For a built-in-tile map that is every image, so the
 * export decodes nothing. `tileSize` is the size the caller wants, and
 * `exportTileSize` reduces it to whatever fits the browser. A node that fits
 * nothing at all resolves to null before any canvas is made, so the caller
 * can tell the GM why no file came.
 * @param {MapNode} node
 * @param {{
 *   tileSize?: number,
 *   regionGroups?: import('./RegionGroups.js').RegionGroup[],
 *   getNodeName?: (nodeId: string) => string | undefined,
 *   imageCache?: Map<string, HTMLImageElement>,
 * }} [options]
 * @returns {Promise<HTMLCanvasElement | null>}
 */
export async function renderNodeToCanvas(node, options = {}) {
  const tileSize = exportTileSize(node, options.tileSize ?? EXPORT_TILE_SIZE);
  if (!tileSize) return null;
  const { width, height, lead } = exportCanvasSize(node, tileSize);
  const canvas = document.createElement('canvas');
  canvas.width = width;
  canvas.height = height;
  const ctx = canvas.getContext('2d');
  if (!ctx) throw new Error('Canvas 2d context unavailable.');

  // Rasterization off: this pass draws each ref once, so a pixel cache saves
  // nothing, and an exported handout must come from the vector art at full
  // size rather than through a quantized raster.
  const renderer = new MapRenderer(ctx, {
    tileSize,
    getNodeName: options.getNodeName,
    rasterize: false,
  });
  const refs = collectImageRefs(node);
  // Seed from the live cache first, then fill the gaps. Copy the entries in
  // instead of sharing the cache, so the export never writes into the cache
  // the live canvas draws from.
  for (const ref of refs) {
    const decoded = options.imageCache?.get(ref);
    if (decoded?.complete) renderer.imageCache.set(ref, decoded);
  }
  await Promise.all(
    refsToDecode(refs, options.imageCache).map(async (ref) => {
      const img = new Image();
      img.src = imageSrcForRef(ref);
      try {
        await img.decode();
      } catch {
        // Art is missing or broken. Leave the image incomplete so the
        // renderer draws its placeholder fill for that tile instead of failing.
      }
      renderer.imageCache.set(ref, img);
    }),
  );

  renderer.render({
    canvasWidth: canvas.width,
    canvasHeight: canvas.height,
    node,
    regionGroups: options.regionGroups ?? [],
    offsetX: lead,
    offsetY: lead,
    scale: 1,
    revealAll: true,
    markerRange: 0,
    partyTileId: null,
    encounterTileIds: [],
    selectedTileId: null,
    cursorCellId: null,
    focused: false,
  });
  return canvas;
}

/**
 * Trigger a browser download of a canvas as a PNG file.
 * @param {HTMLCanvasElement} canvas
 * @param {string} filename
 */
export function downloadCanvasPNG(canvas, filename) {
  canvas.toBlob((blob) => {
    if (blob) downloadBlob(blob, filename);
  }, 'image/png');
}
