import { settleHPBuffs } from '../entities/HPBuffs.js';
import { badge, textButton } from './buttons.js';
import { el } from './dom.js';
import { isGM } from '../view/ViewRole.js';
import { mountConditionsBar } from './ConditionsBar.js';
import { mountExhaustionBar } from './ExhaustionBar.js';
import { mountListPanel } from './listPanel.js';
import { showsCombatBars } from '../view/NpcCard.js';
import { NOTES_FOLD_LENGTH, foldsText } from '../view/TextFold.js';
import { foldText } from './FoldText.js';

/** @typedef {import('../types/creature.js').Creature} NPC */
/** @typedef {import('../types/view.js').ViewRole} ViewRole */

/**
 * How a disposition reads: a friend is good news, a hostile is bad news, and
 * anyone else is neither.
 * @type {Record<NPC['disposition'], 'success' | 'danger' | 'neutral'>}
 */
const DISPOSITION_VARIANTS = { friendly: 'success', neutral: 'neutral', hostile: 'danger' };

/**
 * A location label with a no-break space inside each "column 11" and "row 4",
 * so a narrow row wraps between the parts of the label and not inside one.
 * @param {string} label
 */
export function keepPairs(label) {
  return label.replace(/\b(column|row) (\d+)/g, '$1\u00a0$2');
}

/**
 * Mount the NPC panel: one row per NPC relevant to the party's location. Each
 * row shows name, role, a disposition badge, and notes, with edit and delete
 * controls plus a "New NPC" control. Like the encounter panel, this panel
 * owns no roster state. `getNPCs` supplies the visible rows, and every
 * mutation flows back through a callback. Modals live in main.js. When
 * `getRole` reports a player view, the roster is read-only: rows render
 * without edit or delete, and the panel omits the add control. With `pinAdd`
 * set, the add button leads the list and stays pinned while the list scrolls
 * (the Build rail), instead of trailing the list.
 *
 * With `onUpdate`, a GM row also carries the condition chips, so an NPC drawn
 * into a fight can be marked poisoned or stunned from the same list that
 * shows it. Without the callback the row has no chips, which is what the
 * authoring rail wants. `onSetExhaustion` adds the exhaustion pips beside them,
 * and it is a callback of its own because the sixth level kills the NPC, which
 * is more than a write of one field. With `inFight`, the chips and the pips
 * show only while the NPC is in the fight or still has a condition or a
 * level of exhaustion.
 *
 * `onToggleCompanion` adds a "Travels with party" toggle button with a
 * visible label below the text. Long notes fold to two lines behind a More
 * button, and the panel keeps which cards the GM opened.
 * `getFactionLabel` names the faction of a GM row, beside its role.
 * @param {HTMLElement} container
 * @param {{
 *   getNPCs: () => NPC[],
 *   onDelete: (id: string) => void,
 *   onUpdate?: (npc: NPC) => void,
 *   onSetExhaustion?: (npc: NPC, level: number) => void,
 *   onAdd?: () => Promise<unknown>,
 *   onAddFromTemplate?: () => Promise<unknown>,
 *   onEdit?: (npc: NPC) => Promise<unknown>,
 *   onToggleCompanion?: (npc: NPC) => void,
 *   onBringToParty?: (npc: NPC) => void,
 *   inFight?: (npc: NPC) => boolean,
 *   confirmDelete?: (npc: NPC) => Promise<boolean>,
 *   getLocationLabel?: (npc: NPC) => string,
 *   getFactionLabel?: (npc: NPC) => string,
 *   getRole?: () => ViewRole,
 *   pinAdd?: boolean,
 * }} callbacks
 * @returns {{ update: () => void }}
 */
export function mountNPCPanel(container, callbacks) {
  /** The ids of the NPCs whose long notes the GM opened. @type {Set<string>} */
  const openNotes = new Set();
  const inFight = callbacks.inFight;

  /**
   * The notes, folded to two lines when long, with the More or Less button.
   * @param {NPC} npc
   * @param {() => void} render
   * @returns {Node[]}
   */
  function notesOf(npc, render) {
    if (!npc.notes) return [];
    const open = openNotes.has(npc.id);
    return foldText('span', 'npc-panel__notes', npc.notes, {
      fold: foldsText(npc.notes, NOTES_FOLD_LENGTH),
      open,
      subject: `notes on ${npc.name}`,
      focusKey: `notes:${npc.id}`,
      onToggle: () => {
        if (open) openNotes.delete(npc.id);
        else openNotes.add(npc.id);
        render();
      },
    });
  }

  /**
   * The faction line of a row, or nothing when the NPC has no faction.
   * @param {NPC} npc
   */
  function factionOf(npc) {
    const name = callbacks.getFactionLabel?.(npc);
    return name ? el('span', 'npc-panel__faction', `Faction: ${name}`) : null;
  }

  return mountListPanel(container, {
    // A fight that starts or ends changes which cards show the chips, while
    // the rows stay the same objects.
    dependsOn: () =>
      inFight
        ? callbacks
            .getNPCs()
            .filter((npc) => inFight(npc))
            .map((npc) => npc.id)
            .join(',')
        : null,
    className: 'npc-panel',
    gate: () => !callbacks.getRole || isGM(callbacks.getRole()),
    getRows: () => callbacks.getNPCs(),
    emptyMessage: 'No one of note here.',
    classes: {
      body: 'npc-panel__body u-col',
      actions: 'npc-panel__controls',
      // The head holds the text and the row buttons side by side. The
      // condition chips and the exhaustion pips go below it, at full width,
      // instead of competing with the text for the same line.
      head: 'npc-panel__head',
      add: 'npc-panel__add',
    },
    buildBody: (npc, ctx) => {
      const getLocationLabel = callbacks.getLocationLabel;
      const head = el(
        'div',
        'u-row u-g2',
        el('span', 'npc-panel__name', npc.name),
        badge(npc.disposition, {
          variant: DISPOSITION_VARIANTS[npc.disposition],
          className: 'npc-panel__badge',
        }),
      );

      // Role, location, and notes are each optional. Notes are GM-only, like
      // the notes of a foe, so a player tab lists the NPC without them. The
      // cast is needed because `filter(Boolean)` does not narrow the array's
      // union type for the typechecker.
      return /** @type {Node[]} */ (
        [
          head,
          npc.role && el('span', 'npc-panel__role', npc.role),
          ctx.gm && factionOf(npc),
          getLocationLabel &&
            el('span', 'npc-panel__location u-muted', keepPairs(getLocationLabel(npc))),
          ...(ctx.gm ? notesOf(npc, ctx.render) : []),
        ].filter(Boolean)
      );
    },
    buildExtras: (npc, row, ctx) => {
      if (!ctx.gm) return;
      const { onToggleCompanion } = callbacks;
      if (onToggleCompanion) {
        const travels = npc.travelsWithParty === true;
        const toggle = textButton(
          'Travels with party',
          async () => {
            await onToggleCompanion(npc);
            ctx.render();
          },
          { icon: travels ? 'check' : 'flag', className: 'npc-panel__companion' },
        );
        toggle.setAttribute('aria-pressed', String(travels));
        toggle.dataset.focusKey = `companion:${npc.id}`;
        row.appendChild(toggle);
      }
      if (inFight && !showsCombatBars(npc, inFight(npc))) return;
      const onUpdate = callbacks.onUpdate;
      if (onUpdate) {
        mountConditionsBar(row, {
          getConditions: () => npc.conditions ?? [],
          // The bar reads `npc`, the row's copy from before the edit, so the
          // list repaints its rows to show the stored chips.
          onChange: (next) => {
            onUpdate(settleHPBuffs({ ...npc, conditions: next }));
            ctx.render();
          },
        });
      }
      const onSetExhaustion = callbacks.onSetExhaustion;
      if (onSetExhaustion) {
        mountExhaustionBar(row, {
          getEntity: () => npc,
          onSet: (level) => onSetExhaustion(npc, level),
        });
      }
    },
    actions: (npc, ctx) => {
      if (!ctx.gm) return [];
      const { onBringToParty } = callbacks;
      const onEdit = callbacks.onEdit;
      return [
        onBringToParty
          ? {
              icon: /** @type {const} */ ('give'),
              label: `Bring ${npc.name} to the party`,
              onClick: () => onBringToParty(npc),
            }
          : null,
        onEdit ? { icon: 'edit', label: `Edit ${npc.name}`, onClick: () => onEdit(npc) } : null,
        {
          icon: 'remove',
          label: `Delete ${npc.name}`,
          variant: 'danger',
          onClick: async () => {
            if (callbacks.confirmDelete && !(await callbacks.confirmDelete(npc))) return false;
            callbacks.onDelete(npc.id);
          },
        },
      ];
    },
    addButtons: () => {
      const { onAdd, onAddFromTemplate } = callbacks;
      return [
        onAdd ? { label: 'New NPC', icon: 'add', onClick: onAdd } : null,
        onAddFromTemplate
          ? { label: 'From bestiary', icon: 'scroll', onClick: onAddFromTemplate }
          : null,
      ];
    },
    addPlacement: callbacks.pinAdd ? 'leading' : 'inline',
  });
}
