import { countNoun } from '../util/text.js';
import { el } from './dom.js';
import { chip } from './buttons.js';
import { factLine } from './FactLine.js';
import { formatModifier } from '../entities/Modifiers.js';

/** @typedef {import('../combat/Loadout.js').Loadout} Loadout */

/**
 * A combatant's loadout as a short block of labeled lines: what the
 * combatant wears, what it can swing, how many spells it has, and what
 * is left in its slot pools. The board's cards and the active-combatant
 * column share this block, so the two cannot describe the same
 * combatant differently.
 *
 * `detailed` is the column's fuller form. Weapons print their damage
 * roll, and each slot pool gets a chip. A card gets names and a compact
 * slot summary instead, since a card sits next to five others.
 *
 * The block draws exactly what it is handed. Whether the viewer can see
 * a combatant's spells at all is decided before this point, see
 * `combat/Loadout.js`. This is why an empty list here means nothing to
 * draw, not nothing to know.
 * @param {Loadout} loadout
 * @param {{ detailed?: boolean }} [options]
 * @returns {HTMLElement | null}
 */
export function loadoutBlock(loadout, { detailed = false } = {}) {
  /** @type {HTMLElement[]} */
  const lines = [];

  if (loadout.armor.length > 0) lines.push(line('Wearing', loadout.armor.join(', ')));

  if (loadout.weapons.length > 0) {
    const weapons = loadout.weapons.map((w) => (detailed ? `${w.name} (${w.damage})` : w.name));
    lines.push(line('Weapons', weapons.join(', ')));
  }

  const spells = spellSummary(loadout.spells);
  if (spells) lines.push(line('Spells', spells));

  // The caster's spell save DC and attack bonus, so a player reads the
  // numbers a cast will use without opening the cast dialog.
  if (loadout.spellStats) {
    const stats = loadout.spellStats;
    lines.push(line('Casting', `DC ${stats.dc}, attack ${formatModifier(stats.attack)}`));
  }

  if (loadout.slots.length > 0) {
    lines.push(
      detailed
        ? line(
            'Slots',
            el(
              'span',
              'loadout__chips u-row u-wrap u-g1',
              ...loadout.slots.map((slot) =>
                chip(`${slotLabel(slot)}: ${slot.remaining}/${slot.max}`),
              ),
            ),
          )
        : line('Slots', loadout.slots.map(compactSlot).join(', ')),
    );
  }

  if (lines.length === 0) return null;
  return el('div', `loadout${detailed ? ' loadout--detailed' : ''}`, ...lines);
}

/**
 * One labelled line. The block reads as a table, so the label sits beside
 * its value rather than above it.
 * @param {string} label
 * @param {import('./dom.js').Child} value
 */
function line(label, value) {
  return factLine(label, value, { layout: 'row' });
}

/**
 * The spell counts in words, or null for a combatant with none. Cantrips
 * are counted apart from leveled spells, since a cantrip costs nothing to
 * cast and a leveled spell spends a slot.
 * @param {Loadout['spells']} spells
 * @returns {string | null}
 */
function spellSummary(spells) {
  /** @type {string[]} */
  const parts = [];
  if (spells.cantrips > 0) parts.push(countNoun(spells.cantrips, 'cantrip'));
  if (spells.leveled > 0) parts.push(countNoun(spells.leveled, 'spell'));
  return parts.length > 0 ? parts.join(', ') : null;
}

/**
 * A slot pool's name in the column: the spellbook's wording.
 * @param {Loadout['slots'][number]} slot
 */
function slotLabel(slot) {
  return slot.pact ? `Pact (level ${slot.level})` : `Level ${slot.level}`;
}

/**
 * A slot pool on one line: "L2 1/3". A card has no room for the full label.
 * @param {Loadout['slots'][number]} slot
 */
function compactSlot(slot) {
  return `${slot.pact ? 'Pact' : `L${slot.level}`} ${slot.remaining}/${slot.max}`;
}
