/**
 * Concentration: the one spell effect a caster holds open, what breaks it,
 * and when it runs out. Every function is pure. Each function takes a
 * character or a creature and returns a new one, and the d20 for a
 * concentration save comes from the injected random number generator.
 *
 * A caster holds at most one, in its `concentration` field. The
 * `Concentrating` chip beside it is for display only. `begin` writes it,
 * `drop` removes it, and `tick` keeps its counter equal to the state's own
 * `remaining`, which is the authoritative number.
 */

import { CONCENTRATING, addCondition, removeCondition } from './Conditions.js';
import { spendRiders } from './Riders.js';
import { savingThrow } from './Checks.js';
import { hasConcentrationAdvantage } from './FeatChoices.js';
import { durationInRounds } from './SpellTiming.js';
import { canAct } from './ConditionEffects.js';

/** @typedef {import('../types/entities.js').Character} Character */
/** @typedef {import('../types/entities.js').ConcentrationState} ConcentrationState */
/** @typedef {import('../types/entities.js').Condition} Condition */
/**
 * Anything that can hold a spell open: a party character or a creature.
 * @typedef {{ concentration?: ConcentrationState | null, conditions: Condition[] }} Holder
 */
/** @typedef {import('../types/spell.js').Spell} Spell */
/** @typedef {import('../types/dice.js').RollMode} RollMode */
/** @typedef {import('../types/dice.js').RandomFn} RandomFn */

/** The ability a concentration save is made in. */
export const CONCENTRATION_ABILITY = 'CON';

/**
 * The DC to hold concentration through damage: 10, or half the damage taken
 * when that is higher.
 * @param {number} damage
 * @returns {number}
 */
export function concentrationDC(damage) {
  return Math.max(10, Math.floor(damage / 2));
}

/**
 * Start concentrating on a spell, replacing whatever the character held. A
 * caster gets one effect at a time, and beginning a second ends the first.
 * The countdown comes from the spell's own duration in rounds. An
 * open-ended or day-long duration has none, so it reads null, and the
 * effect lasts until something breaks it.
 *
 * Returns the displaced spell alongside the new character, so the caller
 * can state what was lost and remove that spell's effects from the
 * creatures it was holding.
 * @template {Holder} T
 * @param {T} character
 * @param {Spell} spell
 * @param {number} slotLevel the level the spell was cast at
 * @returns {{ character: T, dropped: ConcentrationState | null }}
 */
export function begin(character, spell, slotLevel) {
  const remaining = durationInRounds(spell.duration);
  /** @type {ConcentrationState} */
  const state = { spellId: spell.id, spellName: spell.name, slotLevel, remaining };
  return {
    character: {
      ...character,
      concentration: state,
      conditions: addCondition(character.conditions, CONCENTRATING, remaining),
    },
    dropped: character.concentration ?? null,
  };
}

/**
 * Stop concentrating, however it ended: voluntarily, on a failed save, when
 * the duration ran out, or on dropping to 0 HP. Removing the chip is part of
 * this action, so no caller must remember both halves.
 * @template {Holder} T
 * @param {T} character
 * @returns {T}
 */
export function drop(character) {
  if (!character.concentration) return character;
  return {
    ...character,
    concentration: null,
    conditions: removeCondition(character.conditions, CONCENTRATING),
  };
}

/**
 * End concentration when the character's chips leave it unable to act. A
 * Paralyzed, Stunned, or Unconscious caster cannot hold a spell, and the
 * Unconscious chip that `killOutright` adds covers a death with no damage.
 * The caller gets the ended spell back, so it can free what the spell held.
 * @template {Holder} T
 * @param {T} character
 * @returns {{ character: T, ended: ConcentrationState | null }}
 */
export function dropIfHelpless(character) {
  const held = character.concentration;
  if (!held || canAct(character.conditions)) return { character, ended: null };
  return { character: drop(character), ended: held };
}

/**
 * The save a concentrating character makes on taking damage: a CON save
 * against `concentrationDC`. A failed save ends the effect. A character
 * holding nothing, or one taking no damage, stays unaffected and reports no
 * save. A character with War Caster rolls the save with advantage.
 *
 * The function reports the whole save, so the caller can log the DC and the
 * roll behind the outcome.
 * @param {Character} character
 * @param {number} damage
 * @param {{ mode?: RollMode, rng?: RandomFn }} [opts]
 * @returns {{
 *   character: Character,
 *   save: (import('./Checks.js').SaveResult & { proficient: boolean }) | null,
 *   dropped: boolean,
 * }}
 */
export function checkOnDamage(character, damage, opts = {}) {
  if (!character.concentration || damage <= 0) {
    return { character, save: null, dropped: false };
  }
  // War Caster adds an advantage slant, which folds in with the chips.
  /** @type {'advantage'[]} */
  const slants = hasConcentrationAdvantage(character) ? ['advantage'] : [];
  const save = savingThrow(character, CONCENTRATION_ABILITY, concentrationDC(damage), {
    slants,
    ...opts,
  });
  // A one-roll rider such as Resistance is used up by this save.
  const conditions = spendRiders(character.conditions, save.rider?.spent);
  const rolled = conditions === character.conditions ? character : { ...character, conditions };
  return {
    character: save.success ? rolled : drop(rolled),
    save,
    dropped: !save.success,
  };
}

/**
 * Spend `rounds` of the effect's duration and drop it when it runs out. A
 * combat round passes 1, and the game clock passes the rounds of a watch. A
 * duration with no round count (open-ended, or measured in days) never
 * expires here.
 *
 * The function rewrites the chip's counter from `remaining` instead of
 * decrementing it. The caller elapses the condition list first, and whatever
 * that does to the chip, the number the GM reads afterward is the state's
 * own number.
 * @template {Holder} T
 * @param {T} character
 * @param {number} [rounds]
 * @returns {{ character: T, expired: boolean }}
 */
export function tick(character, rounds = 1) {
  const held = character.concentration;
  if (!held || held.remaining === null) return { character, expired: false };
  const remaining = held.remaining - rounds;
  if (remaining <= 0) return { character: drop(character), expired: true };
  return {
    character: {
      ...character,
      concentration: { ...held, remaining },
      conditions: addCondition(character.conditions, CONCENTRATING, remaining),
    },
    expired: false,
  };
}
